type LessonSeed = Omit<LearningLesson, "quiz"> & {
  question: string;
  options: [string, string, string];
  answer: number;
  explanation: string;
};

function lesson(seed: LessonSeed): LearningLesson {
  const { question, options, answer, explanation, ...content } = seed;
  return { ...content, quiz: { question, options, answer, explanation } };
}

